local r=fu:GetResolve();local p=r:GetProjectManager():GetCurrentProject();print('LIVE',p:GetName(),'RENDERING',p:IsRenderingInProgress());local t=p:GetCurrentTimeline();print('TIMELINE',t:GetName(),'END',t:GetEndFrame());for _,c in ipairs(t:GetItemListInTrack('video',2)) do if c:GetStart()>4500 and c:GetStart()<4800 then print('INSERT',c:GetName(),c:GetStart(),c:GetEnd(),c:GetProperty('ZoomX'),c:GetProperty('Tilt')) end end